import struct

def png_dims(path):
    with open(path,'rb') as f:
        data=f.read(32)
        if data[:8]!=b'\x89PNG\r\n\x1a\n':
            return None
        # IHDR
        w=struct.unpack('>I', data[16:20])[0]
        h=struct.unpack('>I', data[20:24])[0]
        return (w,h)

def gif_dims(path):
    with open(path,'rb') as f:
        h=f.read(10)
        if h[:6] not in (b'GIF87a',b'GIF89a'):
            return None
        w=struct.unpack('<H', h[6:8])[0]
        h2=struct.unpack('<H', h[8:10])[0]
        return (w,h2)

def jpeg_dims(path):
    with open(path,'rb') as f:
        data=f.read()
    # scan markers
    i=2
    while i < len(data):
        if data[i]!=0xFF:
            i+=1
            continue
        # skip padding FF
        while i<len(data) and data[i]==0xFF:
            i+=1
        if i>=len(data):
            break
        marker=data[i]; i+=1
        if marker in (0xD8,0xD9): # SOI,EOI
            continue
        if marker==0x01 or 0xD0 <= marker <= 0xD7:
            continue
        if i+2>len(data):
            break
        length=struct.unpack('>H', data[i:i+2])[0]
        if marker in (0xC0,0xC1,0xC2,0xC3,0xC5,0xC6,0xC7,0xC9,0xCA,0xCB,0xCD,0xCE,0xCF):
            # SOF
            h=struct.unpack('>H', data[i+3:i+5])[0]
            w=struct.unpack('>H', data[i+5:i+7])[0]
            return (w,h)
        i+=length
    return None

def webp_dims(path):
    with open(path,'rb') as f:
        d=f.read(100)
        if d[:4]!=b'RIFF' or d[8:12]!=b'WEBP':
            return None
        chunk=d[12:16]
        if chunk==b'VP8 ':
            # lossy: 14 bytes frame header? width/height at bytes?
            # VP8 frame: 3 byte frame tag, 3 byte start code, 2 byte width, 2 byte height?
            # Let's parse: after 'VP8 ' + 4 byte size + VP8 data
            # VP8 data starts with frame tag (3 bytes), then 9D 012A (3 bytes), then width/height
            # width: 14 bits little endian? Actually 2 bytes: width = (b0 | (b1&0x3F)<<8) ??? Let's just try.
            # Simpler: search? Use known offsets: width at offset 26-27, height at 28-29 (little endian & 0x3FFF)
            if len(d)<30:
                return None
            w=struct.unpack('<H', d[26:28])[0] & 0x3FFF
            h=struct.unpack('<H', d[28:30])[0] & 0x3FFF
            return (w,h)
        elif chunk==b'VP8L':
            # lossless: 1 byte signature 0x2F, then 4 bytes with width/height?
            # VP8L header: 1 byte 0x2F, then 4 bytes: 14 bits width-1, 14 bits height-1, 1 bit alpha, 3 bits version
            if len(d)<25:
                return None
            b0,b1,b2,b3=d[21],d[22],d[23],d[24]
            w = ((b1 & 0x3F) << 8 | b0) + 1  # Actually? Let's check spec: first 14 bits width
            # According to spec: bits: width 14, height 14...
            # bytes little endian 32-bit: val = b0 | b1<<8 | b2<<16 | b3<<24 ; width = (val & 0x3FFF)+1; height = ((val>>14)&0x3FFF)+1
            val = b0 | (b1<<8) | (b2<<16) | (b3<<24)
            w = (val & 0x3FFF) + 1
            h = ((val>>14) & 0x3FFF) + 1
            return (w,h)
        elif chunk==b'VP8X':
            # extended: width-1 24 bits, height-1 24 bits at offset?
            # VP8X chunk: 1 byte flags, 3 bytes?? Let's parse: after 'VP8X' + size (4 bytes) + 1 byte flags + 3 bytes?? + 3 bytes width-1 + 3 bytes height-1
            # Canvas size at bytes 24-29?
            if len(d)<30:
                return None
            w = (d[24] | (d[25]<<8) | (d[26]<<16)) + 1
            h = (d[27] | (d[28]<<8) | (d[29]<<16)) + 1
            return (w,h)
        else:
            return (chunk,)

def tiff_dims(path):
    with open(path,'rb') as f:
        d=f.read(200)
        if d[:2] not in (b'II',b'MM'):
            return None
        endian='<' if d[:2]==b'II' else '>'
        # skip
        # IFD offset
        off=struct.unpack(endian+'I', d[4:8])[0]
        with open(path,'rb') as ff:
            ff.seek(off)
            n=struct.unpack(endian+'H', ff.read(2))[0]
            w=h=None
            for _ in range(n):
                tag,typ,cnt,val=struct.unpack(endian+'HHI4s', ff.read(12))
                if tag==256:
                    if typ==3:
                        w=struct.unpack(endian+'H', val[:2])[0]
                    elif typ==4:
                        w=struct.unpack(endian+'I', val)[0]
                elif tag==257:
                    if typ==3:
                        h=struct.unpack(endian+'H', val[:2])[0]
                    elif typ==4:
                        h=struct.unpack(endian+'I', val)[0]
            return (w,h)

