    var w, h C.int
    ret := C.WebPGetInfo((*C.uchar)(unsafe.Pointer(&data[0])), C.ulong(len(data)), &w, &h)
    fmt.Println("WebPGetInfo ret", ret, "w", w, "h", h)
    var w2, h2 C.int
    ptr := C.WebPDecodeRGBA((*C.uchar)(unsafe.Pointer(&data[0])), C.ulong(len(data)), &w2, &h2)
    if ptr == nil {
        fmt.Println("decode failed")
        return
    }
    fmt.Println("decoded", w2, h2)
    // encode back lossy q80
    var out *C.uchar
    sz := C.WebPEncodeRGBA(ptr, w2, h2, w2*4, 80, &out)
    fmt.Println("encoded lossy sz", sz)
    if out != nil {
        C.WebPFree(unsafe.Pointer(out))
    }
    // lossless
    var out2 *C.uchar
    sz2 := C.WebPEncodeLosslessRGBA(ptr, w2, h2, w2*4, &out2)
    fmt.Println("encoded lossless sz", sz2)
    if out2 != nil {
        C.WebPFree(unsafe.Pointer(out2))
    }
