    "image/color"
    "image/gif"
    "image/jpeg"
    "image/png"
    "io"
    "os"
    "strconv"
    "unsafe"
)

func main() {
    // Helper CLI: helper --input <in> --output <out> [options]
    // Returns 0 on success, 1 on same-format error, 2 on other error
    // For info: helper --info <input> prints "format width height" or exits 1 if invalid
    args := os.Args[1:]
    if len(args) >= 2 && args[0] == "--info" {
        format, w, h, err := getInfo(args[1])
        if err != nil {
            os.Exit(1)
        }
        fmt.Printf("%s %d %d\n", format, w, h)
        os.Exit(0)
    }
    // Parse compress args
    var input, output, formatStr, chroma string
    var quality *int
    var lossless bool
    var maxSize *int64
    var width, height, longEdge, shortEdge int
    var noUpscale, baseline, exif, stripICC, zopfli bool
    var pngOpt int = 3
    // Simple arg parsing: --key value or --key=value or --flag
    for i := 0; i < len(args); i++ {
        a := args[i]
        var key, val string
        var hasVal bool
        if len(a) > 2 && a[0:2] == "--" {
            if eq := indexOf(a, "="); eq >= 0 {
                key = a[0:eq]
                val = a[eq+1:]
                hasVal = true
            } else {
                key = a
                // check if next is value (not starting with --)
                if i+1 < len(args) && !(len(args[i+1]) >= 2 && args[i+1][0:2] == "--") {
                    // For flags, don't consume? Need to know which take values
                    if key == "--input" || key == "--output" || key == "--quality" || key == "--max-size" || key == "--width" || key == "--height" || key == "--long-edge" || key == "--short-edge" || key == "--format" || key == "--png-opt-level" || key == "--jpeg-chroma-subsampling" {
                        val = args[i+1]
                        hasVal = true
                        i++
                    }
                }
            }
        } else {
            fmt.Fprintf(os.Stderr, "unknown arg %s\n", a)
            os.Exit(2)
        }
        switch key {
        case "--input":
            if !hasVal { fmt.Fprintln(os.Stderr, "missing value"); os.Exit(2) }
            input = val
        case "--output":
            if !hasVal { fmt.Fprintln(os.Stderr, "missing value"); os.Exit(2) }
            output = val
        case "--quality":
            if !hasVal { fmt.Fprintln(os.Stderr, "missing value"); os.Exit(2) }
            q, _ := strconv.Atoi(val)
            quality = &q
        case "--lossless":
            lossless = true
        case "--max-size":
            if !hasVal { fmt.Fprintln(os.Stderr, "missing value"); os.Exit(2) }
            ms, _ := strconv.ParseInt(val, 10, 64)
            maxSize = &ms
        case "--width":
            width, _ = strconv.Atoi(val)
        case "--height":
            height, _ = strconv.Atoi(val)
        case "--long-edge":
            longEdge, _ = strconv.Atoi(val)
        case "--short-edge":
            shortEdge, _ = strconv.Atoi(val)
        case "--no-upscale":
            noUpscale = true
        case "--format":
            formatStr = val
        case "--png-opt-level":
            pngOpt, _ = strconv.Atoi(val)
        case "--jpeg-chroma-subsampling":
            chroma = val
        case "--jpeg-baseline":
            baseline = true
        case "--exif":
            exif = true
        case "--strip-icc":
            stripICC = true
        case "--zopfli":
            zopfli = true
        default:
            fmt.Fprintf(os.Stderr, "unknown key %s\n", key)
            os.Exit(2)
        }
    }
    _ = zopfli
    _ = pngOpt
    _ = chroma
    _ = baseline
    _ = stripICC
    if input == "" || output == "" {
        fmt.Fprintln(os.Stderr, "missing input/output")
        os.Exit(2)
    }
    if formatStr == "" {
        formatStr = "original"
    }
    err := compress(input, output, quality, lossless, maxSize, width, height, longEdge, shortEdge, noUpscale, formatStr, exif)
    if err != nil {
        if err.Error() == "SAME_FORMAT" {
            os.Exit(10) // same-format error
        }
        fmt.Fprintln(os.Stderr, err.Error())
        os.Exit(2)
    }
    os.Exit(0)
}

func indexOf(s, substr string) int {
    for i := 0; i+len(substr) <= len(s); i++ {
        if s[i:i+len(substr)] == substr {
            return i
        }
    }
    return -1
}

func getInfo(path string) (string, int, int, error) {
    data, err := os.ReadFile(path)
    if err != nil {
        return "", 0, 0, err
    }
    // Try JPEG
    if len(data) >= 2 && data[0] == 0xFF && data[1] == 0xD8 {
        cfg, err := jpeg.DecodeConfig(bytes.NewReader(data))
        if err == nil {
            return "jpeg", cfg.Width, cfg.Height, nil
        }
    }
    // Try PNG
    if len(data) >= 8 && string(data[0:8]) == "\x89PNG\r\n\x1a\n" {
        cfg, err := png.DecodeConfig(bytes.NewReader(data))
        if err == nil {
            return "png", cfg.Width, cfg.Height, nil
        }
    }
    // Try GIF
    if len(data) >= 6 && (string(data[0:6]) == "GIF87a" || string(data[0:6]) == "GIF89a") {
        cfg, err := gif.DecodeConfig(bytes.NewReader(data))
        if err == nil {
            return "gif", cfg.Width, cfg.Height, nil
        }
    }
    // Try WebP via libwebp
    if len(data) >= 12 && string(data[0:4]) == "RIFF" && string(data[8:12]) == "WEBP" {
        var w, h C.int
        ret := C.WebPGetInfo((*C.uchar)(unsafe.Pointer(&data[0])), C.ulong(len(data)), &w, &h)
        if ret != 0 {
            return "webp", int(w), int(h), nil
        }
    }
    return "", 0, 0, fmt.Errorf("unsupported")
}

