func resizeImage(src image.Image, tw, th int) image.Image {
    // Bilinear resize to RGBA
    sw := src.Bounds().Dx()
    sh := src.Bounds().Dy()
    if sw == tw && sh == th {
        return src
    }
    dst := image.NewRGBA(image.Rect(0, 0, tw, th))
    // Bilinear
    for y := 0; y < th; y++ {
        // srcY
        var srcY float64
        if th == 1 {
            srcY = float64(sh-1) / 2
        } else {
            srcY = float64(y) * float64(sh-1) / float64(th-1)
        }
        y0 := int(srcY)
        y1 := y0 + 1
        if y1 >= sh {
            y1 = sh - 1
        }
        fy := srcY - float64(y0)
        for x := 0; x < tw; x++ {
            var srcX float64
            if tw == 1 {
                srcX = float64(sw-1) / 2
            } else {
                srcX = float64(x) * float64(sw-1) / float64(tw-1)
            }
            x0 := int(srcX)
            x1 := x0 + 1
            if x1 >= sw {
                x1 = sw - 1
            }
            fx := srcX - float64(x0)
            // Get 4 pixels
            c00 := color.RGBAModel.Convert(src.At(src.Bounds().Min.X+x0, src.Bounds().Min.Y+y0)).(color.RGBA)
            c10 := color.RGBAModel.Convert(src.At(src.Bounds().Min.X+x1, src.Bounds().Min.Y+y0)).(color.RGBA)
            c01 := color.RGBAModel.Convert(src.At(src.Bounds().Min.X+x0, src.Bounds().Min.Y+y1)).(color.RGBA)
            c11 := color.RGBAModel.Convert(src.At(src.Bounds().Min.X+x1, src.Bounds().Min.Y+y1)).(color.RGBA)
            r := float64(c00.R)*(1-fx)*(1-fy) + float64(c10.R)*fx*(1-fy) + float64(c01.R)*(1-fx)*fy + float64(c11.R)*fx*fy
            g := float64(c00.G)*(1-fx)*(1-fy) + float64(c10.G)*fx*(1-fy) + float64(c01.G)*(1-fx)*fy + float64(c11.G)*fx*fy
            b := float64(c00.B)*(1-fx)*(1-fy) + float64(c10.B)*fx*(1-fy) + float64(c01.B)*(1-fx)*fy + float64(c11.B)*fx*fy
            a := float64(c00.A)*(1-fx)*(1-fy) + float64(c10.A)*fx*(1-fy) + float64(c01.A)*(1-fx)*fy + float64(c11.A)*fx*fy
            dst.SetRGBA(x, y, color.RGBA{uint8(r + 0.5), uint8(g + 0.5), uint8(b + 0.5), uint8(a + 0.5)})
        }
    }
    return dst
}

func resizeGif(g *gif.GIF, tw, th, ow, oh int) *gif.GIF {
    out := &gif.GIF{
        Image:     make([]*image.Paletted, len(g.Image)),
        Delay:     append([]int(nil), g.Delay...),
        LoopCount: g.LoopCount,
        Disposal:  append([]byte(nil), g.Disposal...),
        Config: image.Config{
            Width:      tw,
            Height:     th,
            ColorModel: g.Config.ColorModel,
        },
        BackgroundIndex: g.BackgroundIndex,
    }
    for i, frame := range g.Image {
        // Convert paletted to RGBA, resize, then back to paletted with same palette?
        // For simplicity, resize RGBA then quantize to original palette (nearest)?
        rgba := image.NewRGBA(frame.Bounds())
        // Draw frame onto rgba? Need to handle disposal? Simplify: just convert frame pixels
        for y := 0; y < frame.Bounds().Dy(); y++ {
            for x := 0; x < frame.Bounds().Dx(); x++ {
                rgba.Set(x, y, frame.At(x+frame.Bounds().Min.X, y+frame.Bounds().Min.Y))
            }
        }
        resizedRGBA := resizeImage(rgba, tw, th)
        // Convert back to paletted using original palette (nearest color)
        pal := frame.Palette
        if pal == nil {
            pal = g.Image[0].Palette
        }
        paletted := image.NewPaletted(image.Rect(0, 0, tw, th), pal)
        for y := 0; y < th; y++ {
            for x := 0; x < tw; x++ {
                c := resizedRGBA.At(x, y)
                // Find nearest in palette
                paletted.ColorIndexAt(x, y)
                idx := nearestColorIndex(c, pal)
                paletted.SetColorIndex(x, y, uint8(idx))
            }
        }
        // Preserve bounds offset? Original frames may have offset (for animation with disposal). Simplify: set bounds to 0,0,tw,th
        out.Image[i] = paletted
    }
    return out
}

func nearestColorIndex(c color.Color, pal color.Palette) int {
    r1, g1, b1, _ := c.RGBA()
    best := 0
    bestDist := uint32(1<<32 - 1)
    for i, pc := range pal {
        r2, g2, b2, _ := pc.RGBA()
        dr := int32(r1>>8) - int32(r2>>8)
        dg := int32(g1>>8) - int32(g2>>8)
        db := int32(b1>>8) - int32(b2>>8)
        dist := uint32(dr*dr + dg*dg + db*db)
        if dist < bestDist {
            bestDist = dist
            best = i
            if dist == 0 {
                break
            }
        }
    }
    return best
}

func imageToGif(img image.Image, quality *int, lossless bool) *gif.GIF {
    q := 80
    if quality != nil {
        q = *quality
    }
    var pal color.Palette
    if lossless {
        pal = medianCutPalette(img, 256)
    } else {
        ncolors := 256
        if q <= 10 {
            ncolors = 32
        } else if q <= 30 {
            ncolors = 64
        } else if q <= 60 {
            ncolors = 128
        } else {
            ncolors = 256
        }
        pal = medianCutPalette(img, ncolors)
    }
    bounds := img.Bounds()
    paletted := image.NewPaletted(image.Rect(0, 0, bounds.Dx(), bounds.Dy()), pal)
    for y := 0; y < bounds.Dy(); y++ {
        for x := 0; x < bounds.Dx(); x++ {
            c := img.At(bounds.Min.X+x, bounds.Min.Y+y)
            idx := nearestColorIndex(c, pal)
            paletted.SetColorIndex(x, y, uint8(idx))
        }
    }
    return &gif.GIF{
        Image: []*image.Paletted{paletted},
        Delay: []int{0},
        Config: image.Config{Width: bounds.Dx(), Height: bounds.Dy()},
    }
}

func encodeGifWithQuality(g *gif.GIF, q int) []byte {
    // Re-quantize each frame to fewer colors based on q?
    // For simplicity, if q high, keep as is; if low, reduce colors
    var ng *gif.GIF
    if q >= 80 {
        ng = g
    } else {
        ncolors := 256
        if q <= 10 {
            ncolors = 32
        } else if q <= 30 {
            ncolors = 64
        } else if q <= 60 {
            ncolors = 128
        }
        ng = quantizeGif(g, ncolors)
    }
    var buf bytes.Buffer
    // Use default encoder (which will write palette)
    err := gif.EncodeAll(&buf, ng)
    if err != nil {
        return nil
    }
    return buf.Bytes()
}

func encodeGifLossless(g *gif.GIF) []byte {
    var buf bytes.Buffer
    gif.EncodeAll(&buf, g)
    return buf.Bytes()
