use clap::{Arg, ArgAction, ArgGroup, Command, value_parser};
use clap::builder::{PossibleValuesParser, PossibleValue};
use std::path::{Path, PathBuf};
use std::process::ExitCode;

fn parse_quality(s: &str) -> Result<u32, String> {
    match s.parse::<u32>() {
        Ok(v) => {
            if v > 100 {
                Err(format!("Quality must be between 0 and 100, but got {}", v))
            } else {
                Ok(v)
            }
        }
        Err(_) => Err(format!("'{}' is not a valid number", s)),
    }
}
fn parse_png_opt(s: &str) -> Result<u8, String> {
    match s.parse::<u8>() {
        Ok(v) => {
            if v > 6 {
                Err(format!("PNG optimization level must be between 0 and 6, but got {}", v))
            } else {
                Ok(v)
            }
        }
        Err(_) => Err(format!("'{}' is not a valid number", s)),
    }
}
fn parse_verbose(s: &str) -> Result<u8, String> {
    match s.parse::<u8>() {
        Ok(v) => {
            if v > 3 {
                Err(format!("Verbosity must be between 0 and 3, but got {}", v))
            } else {
                Ok(v)
            }
        }
        Err(_) => Err(format!("'{}' is not a valid number", s)),
    }
}
fn parse_u32_range(s: &str) -> Result<u32, String> {
    // Parse as i64 then check 0..=u32::MAX, to match original's messages for width/threads
    // For "abc", i64 parse gives "invalid digit found in string" (same as u32)
    // For "", gives "cannot parse integer from empty string"
    // For "-5" or overflow, give range message
    match s.parse::<i64>() {
        Ok(v) => {
            if v < 0 || v > u32::MAX as i64 {
                Err(format!("{} is not in 0..=4294967295", s))
            } else {
                Ok(v as u32)
            }
        }
        Err(e) => {
            // Need to return same message as e.to_string()? For "abc", e is "invalid digit found in string", for "" is "cannot parse integer from empty string"
            // Clap will prefix with "invalid value ..."? Actually value_parser error string is displayed as is after colon? For custom parser returning String, clap shows that string. For standard parser, it shows e.to_string(). To match, return e.to_string()
            Err(e.to_string())
        }
    }
}

fn main() {
    let cmd = Command::new("caesiumclt")
        .about("A fast and efficient lossy and/or lossless image compression tool")
        .version("1.3.0")
        .arg(Arg::new("quality").short('q').long("quality").value_name("QUALITY").help("Compression quality [0-100], higher values mean better quality").value_parser(parse_quality))
        .arg(Arg::new("lossless").long("lossless").action(ArgAction::SetTrue).help("Use lossless compression (may increase file size for some formats)"))
        .arg(Arg::new("max-size").long("max-size").value_name("MAX_SIZE").help("Target maximum file size in bytes or human-readable format (e.g., 100KB, 0.5MB)").value_parser(parse_max_size))
        .group(ArgGroup::new("compression").args(["quality", "lossless", "max-size"]).required(true).multiple(false))
        .arg(Arg::new("width").long("width").value_name("WIDTH").help("Output image width in pixels (preserves the aspect ratio if height not set)").value_parser(parse_u32_range).conflicts_with_all(["long-edge", "short-edge"]))
        .arg(Arg::new("height").long("height").value_name("HEIGHT").help("Output image height in pixels (preserves the aspect ratio if width not set)").value_parser(parse_u32_range).conflicts_with_all(["long-edge", "short-edge"]))
        .arg(Arg::new("long-edge").long("long-edge").value_name("LONG_EDGE").help("Size in pixels for the longest edge of the image").value_parser(parse_u32_range).conflicts_with_all(["width", "height", "short-edge"]))
        .arg(Arg::new("short-edge").long("short-edge").value_name("SHORT_EDGE").help("Size in pixels for the shortest edge of the image").value_parser(parse_u32_range).conflicts_with_all(["width", "height", "long-edge"]))
        .arg(Arg::new("no-upscale").long("no-upscale").action(ArgAction::SetTrue).help("Prevents upscaling of the image when resizing"))
        .arg(Arg::new("output").short('o').long("output").value_name("OUTPUT").help("Output directory path"))
        .arg(Arg::new("same-folder-as-input").long("same-folder-as-input").action(ArgAction::SetTrue).help("Use input file's directory as output (WARNING: may overwrite originals)"))
        .group(ArgGroup::new("destination").args(["output", "same-folder-as-input"]).required(true).multiple(false))
        .arg(Arg::new("format").long("format").value_name("FORMAT").help("Convert to the selected output format or keep the original").value_parser(PossibleValuesParser::new(["jpeg", "png", "gif", "webp", "tiff", "original"])).default_value("original"))
        .arg(Arg::new("png-opt-level").long("png-opt-level").value_name("PNG_OPT_LEVEL").help("PNG optimization level [0-6], higher values provide better compression").value_parser(parse_png_opt).default_value("3"))
        .arg(Arg::new("jpeg-chroma-subsampling").long("jpeg-chroma-subsampling").value_name("JPEG_CHROMA_SUBSAMPLING").help("Chroma subsampling for JPEG files").value_parser(PossibleValuesParser::new(["4:4:4", "4:2:2", "4:2:0", "4:1:1", "auto"])).default_value("auto"))
        .arg(Arg::new("jpeg-baseline").long("jpeg-baseline").action(ArgAction::SetTrue).help("Output baseline JPEG instead of progressive (default)"))
        .arg(Arg::new("zopfli").long("zopfli").action(ArgAction::SetTrue).help("Use zopfli for PNG optimization (significantly slower but better compression)"))
        .arg(Arg::new("exif").short('e').long("exif").action(ArgAction::SetTrue).help("Keep EXIF metadata during compression"))
        .arg(Arg::new("keep-dates").long("keep-dates").action(ArgAction::SetTrue).help("Preserve original file timestamps"))
        .arg(Arg::new("strip-icc").long("strip-icc").action(ArgAction::SetTrue).help("Strips ICC profile info on JPG files, ignoring the -e flag"))
        .arg(Arg::new("suffix").long("suffix").value_name("SUFFIX").help("Add suffix to output filenames"))
        .arg(Arg::new("recursive").short('R').long("recursive").action(ArgAction::SetTrue).help("Scan subfolders recursively when input is a directory"))
        .arg(Arg::new("keep-structure").short('S').long("keep-structure").action(ArgAction::SetTrue).help("Preserve directory structure (requires -R/--recursive)"))
        .arg(Arg::new("dry-run").short('d').long("dry-run").action(ArgAction::SetTrue).help("Simulate compression without writing files"))
        .arg(Arg::new("threads").long("threads").value_name("THREADS").help("Number of parallel jobs (0 = auto-detect, max = available processors)").value_parser(parse_u32_range).default_value("0"))
        .arg(Arg::new("overwrite").short('O').long("overwrite").value_name("OVERWRITE").help("Policy for handling existing output files").value_parser(PossibleValuesParser::new([PossibleValue::new("all").help("Always overwrite existing files"), PossibleValue::new("never").help("Never overwrite existing files"), PossibleValue::new("bigger").help("Overwrite only if the existing file is bigger")])).default_value("all"))
        .arg(Arg::new("min-savings").long("min-savings").value_name("MIN_SAVINGS").help("Minimum compression savings required to write an output file. Use percentage (e.g., '10%', '1.5%'), absolute size (e.g., '100KB', '1MB'), or plain number as bytes").value_parser(parse_min_savings))
