fn jpeg_dims(data: &[u8]) -> Option<(u32, u32)> {
    if data.len() < 2 || data[0] != 0xFF || data[1] != 0xD8 {
        return None;
    }
    let mut i = 2;
    while i < data.len() {
        if data[i] != 0xFF {
            i += 1;
            continue;
        }
        while i < data.len() && data[i] == 0xFF {
            i += 1;
        }
        if i >= data.len() {
            break;
        }
        let marker = data[i];
        i += 1;
        if marker == 0xD8 || marker == 0xD9 {
            continue;
        }
        if marker == 0x01 || (marker >= 0xD0 && marker <= 0xD7) {
            continue;
        }
        if i + 2 > data.len() {
            break;
        }
        let len = ((data[i] as usize) << 8) | (data[i+1] as usize);
        if len < 2 {
            break;
        }
        if matches!(marker, 0xC0|0xC1|0xC2|0xC3|0xC5|0xC6|0xC7|0xC9|0xCA|0xCB|0xCD|0xCE|0xCF) {
            if i + 7 > data.len() {
                break;
            }
            let h = ((data[i+3] as u32) << 8) | (data[i+4] as u32);
            let w = ((data[i+5] as u32) << 8) | (data[i+6] as u32);
            if w == 0 || h == 0 {
                return None;
            }
            return Some((w, h));
        }
        i += len;
    }
    None
}

fn png_dims(data: &[u8]) -> Option<(u32, u32)> {
    if data.len() < 24 {
        return None;
    }
    if data[0..8] != [0x89, b'P', b'N', b'G', 0x0D, 0x0A, 0x1A, 0x0A] {
        return None;
    }
    // IHDR chunk: length (4) + type (4) + data (13) + CRC (4). At offset 8: length (should be 13), type "IHDR", then width, height.
    // Check length and type?
    let len = u32::from_be_bytes([data[8], data[9], data[10], data[11]]);
    if len != 13 {
        return None;
    }
    if &data[12..16] != b"IHDR" {
        return None;
    }
    let w = u32::from_be_bytes([data[16], data[17], data[18], data[19]]);
    let h = u32::from_be_bytes([data[20], data[21], data[22], data[23]]);
    if w == 0 || h == 0 {
        return None;
    }
    Some((w, h))
}

fn gif_dims(data: &[u8]) -> Option<(u32, u32)> {
    if data.len() < 10 {
        return None;
    }
    if &data[0..6] != b"GIF87a" && &data[0..6] != b"GIF89a" {
        return None;
    }
    let w = u16::from_le_bytes([data[6], data[7]]) as u32;
    let h = u16::from_le_bytes([data[8], data[9]]) as u32;
    if w == 0 || h == 0 {
