import subprocess, os, shutil, tempfile, struct
def gif_dims(p):
    with open(p,'rb') as f: d=f.read(10)
    return (struct.unpack('<H',d[6:8])[0], struct.unpack('<H',d[8:10])[0])
def png_dims(p):
    import struct
    with open(p,'rb') as f: d=f.read(30)
    return (struct.unpack('>I',d[16:20])[0], struct.unpack('>I',d[20:24])[0])
def jpeg_dims(p):
    with open(p,'rb') as f: d=f.read()
    import struct
    i=2
    while i<len(d):
        if d[i]!=0xFF:
            i+=1; continue
        while d[i]==0xFF: i+=1
        m=d[i]; i+=1
        if m in (0xD8,0xD9): continue
        if m==0x01 or 0xD0<=m<=0xD7: continue
        ln=struct.unpack('>H',d[i:i+2])[0]
        if m in (0xC0,0xC1,0xC2,0xC3,0xC5,0xC6,0xC7,0xC9,0xCA,0xCB,0xCD,0xCE,0xCF):
            h=struct.unpack('>H',d[i+3:i+5])[0]; w=struct.unpack('>H',d[i+5:i+7])[0]
            return (w,h)
        i+=ln
    return None

ORIG=os.path.abspath("./executable")
