    os.makedirs(os.path.join(tmp,"out"))
    shutil.copy(f"assets/{src}", os.path.join(tmp,src))
    p=subprocess.run([ORIG,"-q","80","--format",fmt,"-o","out",src], capture_output=True, cwd=tmp)
    outdir=os.path.join(tmp,"out")
    files=os.listdir(outdir) if os.path.exists(outdir) else []
    print(f"{src}->{fmt} files={files}")
    for f in files:
