        elif f.endswith(".png"):
            print(" ",png_dims(path), os.path.getsize(path))
        elif f.endswith(".jpg"):
            print(" ",jpeg_dims(path), os.path.getsize(path))
        else:
            print(" ",os.path.getsize(path))
    shutil.rmtree(tmp)
